t.script:
document.addEventListener('DOMContentLoaded', function() {
    // Fetch dashboard data
    fetch('/my/product_requests/dashboard/data', {
        method: 'POST',
        headers: {
            'Content-Type': 'application/json',
        },
        body: JSON.stringify({
            jsonrpc: '2.0',
            method: 'call',
            params: {}
        })
    })
    .then(response => response.json())
    .then(data => {
        if (data.result) {
            updateDashboard(data.result);
        }
    })
    .catch(error => console.error('Error:', error));
});

function updateDashboard(data) {
    // Update statistics cards
    document.getElementById('totalRequests').textContent = data.total_requests || 0;
    document.getElementById('totalItems').textContent = data.total_items || 0;

    // Calculate pending and approved
    let pending = 0;
    let approved = 0;
    for (let [status, count] of Object.entries(data.status_counts || {})) {
        if (status === 'Submitted' || status === 'Draft') {
            pending += count;
        } else if (status === 'Approved') {
            approved += count;
        }
    }
    document.getElementById('pendingRequests').textContent = pending;
    document.getElementById('approvedRequests').textContent = approved;

    // Status Pie Chart
    const statusLabels = Object.keys(data.status_counts || {});
    const statusData = Object.values(data.status_counts || {});

    if (statusLabels.length > 0) {
        const statusOptions = {
            series: statusData,
            chart: {
                type: 'donut',
                height: 350
            },
            labels: statusLabels,
            colors: ['#17a2b8', '#ffc107', '#28a745', '#dc3545', '#6c757d'],
            legend: {
                position: 'bottom'
            },
            responsive: [{
                breakpoint: 480,
                options: {
                    chart: {
                        width: 300
                    },
                    legend: {
                        position: 'bottom'
                    }
                }
            }]
        };
        const statusChart = new ApexCharts(document.querySelector("#statusChart"), statusOptions);
        statusChart.render();
    }

    // Monthly Trend Line Chart
    const monthlyLabels = (data.monthly_trend || []).map(item => item.month);
    const monthlyData = (data.monthly_trend || []).map(item => item.count);

    if (monthlyLabels.length > 0) {
        const monthlyOptions = {
            series: [{
                name: 'Requests / الطلبات',
                data: monthlyData
            }],
            chart: {
                type: 'area',
                height: 350,
                toolbar: {
                    show: false
                }
            },
            dataLabels: {
                enabled: false
            },
            stroke: {
                curve: 'smooth',
                width: 2
            },
            xaxis: {
                categories: monthlyLabels
            },
            colors: ['#28a745'],
            fill: {
                type: 'gradient',
                gradient: {
                    opacityFrom: 0.6,
                    opacityTo: 0.1
                }
            }
        };
        const monthlyChart = new ApexCharts(document.querySelector("#monthlyChart"), monthlyOptions);
        monthlyChart.render();
    }

    // Top Products Bar Chart
    const productNames = (data.top_products || []).map(p => p.name.length > 20 ? p.name.substring(0, 20) + '...' : p.name);
    const productCounts = (data.top_products || []).map(p => p.count);

    if (productNames.length > 0) {
        const topProductsOptions = {
            series: [{
                name: 'Request Count / عدد الطلبات',
                data: productCounts
            }],
            chart: {
                type: 'bar',
                height: 400,
                toolbar: {
                    show: false
                }
            },
            plotOptions: {
                bar: {
                    horizontal: true,
                    dataLabels: {
                        position: 'top'
                    }
                }
            },
            dataLabels: {
                enabled: true,
                offsetX: 30,
                style: {
                    fontSize: '12px',
                    colors: ['#304758']
                }
            },
            xaxis: {
                categories: productNames
            },
            colors: ['#17a2b8'],
            grid: {
                borderColor: '#f1f1f1'
            }
        };
        const topProductsChart = new ApexCharts(document.querySelector("#topProductsChart"), topProductsOptions);
        topProductsChart.render();
    }
}

form.script:
// Form validation before submit
document.addEventListener('DOMContentLoaded', function() {
    const form = document.querySelector('form');
    form.addEventListener('submit', function(e) {
        const productLines = document.querySelectorAll('.product-line');
        if (productLines.length === 0) {
            e.preventDefault();
            alert('Please add at least one product line / الرجاء إضافة منتج واحد على الأقل');
            return false;
        }
        return true;
    });
});
// Store products and UOMs data
const productsData = [

        {id: , name: '', uom_category_id: },

];

const uomsData = [

        {id: , name: '', category_id: },

];

let lineCounter = 0;

function addProductLine() {
    lineCounter++;
    const container = document.getElementById('product_lines');
    const lineDiv = document.createElement('div');
    lineDiv.className = 'row mb-3 product-line';
    lineDiv.id = 'line_' + lineCounter;

    // Build product options
    let productOptions = 'Select Product / اختر منتج';
    productsData.forEach(product => {
        productOptions += `${product.name}`;
    });

    // Build UOM options
    let uomOptions = 'Select Unit / اختر وحدة';
    uomsData.forEach(uom => {
        uomOptions += `${uom.name}`;
    });

    lineDiv.innerHTML = `


            Product / المنتج

                ` + productOptions + `




            Quantity / الكمية




            Unit / الوحدة

                ` + uomOptions + `









    `;
    container.appendChild(lineDiv);

    // Add event listener for product change to filter UOMs
    const productSelect = lineDiv.querySelector('.product-select');
    const uomSelect = lineDiv.querySelector('.uom-select');

    productSelect.addEventListener('change', function() {
        const productId = parseInt(this.value);
        if (!productId) {
            // Reset UOM options
            uomSelect.innerHTML = 'Select Unit / اختر وحدة';
            uomsData.forEach(uom => {
                uomSelect.innerHTML += `${uom.name}`;
            });
            return;
        }

        // Find the product
        const product = productsData.find(p => p.id === productId);
        if (!product || !product.uom_category_id) {
            return;
        }

        // Filter UOMs by category
        uomSelect.innerHTML = 'Select Unit / اختر وحدة';
        const filteredUoms = uomsData.filter(uom => uom.category_id === product.uom_category_id);
        filteredUoms.forEach(uom => {
            uomSelect.innerHTML += `${uom.name}`;
        });

        // Select the product's default UOM if available
        const defaultOption = uomSelect.querySelector(`option[value="${product.uom_category_id}"]`);
        if (defaultOption) {
            uomSelect.value = product.uom_category_id;
        }
    });
}

function removeProductLine(lineId) {
    const line = document.getElementById('line_' + lineId);
    if (line) {
        line.remove();
    }
}

// Add first line by default
document.addEventListener('DOMContentLoaded', function() {
    addProductLine();
});
